=== FILE: prefix_validator.py ===
"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    pattern_segments = subscribed_pattern.split("::")
    topic_segments = event_topic.split("::")

    # If the subscribed pattern does not end with a wildcard, it implicitly means "::**"
    # to match sub-hierarchies, e.g., "orders" matches "orders::created".
    if pattern_segments and not (pattern_segments[-1] == "*" or pattern_segments[-1] == "**"):
        pattern_segments.append("**")

    p_idx = 0
    t_idx = 0

    while p_idx < len(pattern_segments) and t_idx < len(topic_segments):
        pattern_segment = pattern_segments[p_idx]
        topic_segment = topic_segments[t_idx]

        if pattern_segment == "**":
            # Double asterisk matches arbitrary multi-segment prefixes.
            # It can match zero or more segments.
            # Try to match the rest of the pattern against the rest of the topic.
            # If the rest of the pattern can be matched from any point in the rest of the topic, return True.
            # If "**" is the last segment, it matches everything remaining.
            if p_idx == len(pattern_segments) - 1:
                return True

            # Try to match the next pattern segment from the current topic segment onwards
            next_pattern_segment = pattern_segments[p_idx + 1]
            for i in range(t_idx, len(topic_segments)):
                if is_topic_subscribed("::".join(pattern_segments[p_idx + 1:]), "::".join(topic_segments[i:])):
                    return True
            return False

        elif pattern_segment == "*":
            # Single asterisk matches exactly one segment.
            p_idx += 1
            t_idx += 1
        elif pattern_segment == topic_segment:
            # Exact match for a segment.
            p_idx += 1
            t_idx += 1
        else:
            # Mismatch.
            return False

    # After loop, both must be exhausted for a full match, unless the pattern ends with "**"
    # If pattern ends with "**", it can match an empty sequence of remaining topic segments.
    if p_idx == len(pattern_segments) - 1 and pattern_segments[p_idx] == "**":
        return True

    return p_idx == len(pattern_segments) and t_idx == len(topic_segments)

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
